local MaidCoffeeGuestOptionCell = Class('MaidCoffeeGuestOptionCell')
---@type MaidCoffeeConstants
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")

function MaidCoffeeGuestOptionCell:__init()
    self.callBack = nil
end

function MaidCoffeeGuestOptionCell:__delete()
    self.callBack = nil
end

function MaidCoffeeGuestOptionCell:Awake()
    SetButtonAction(self.OptionNode1.gameObject,Bind(self,self.OnOptionNodeClick))
end

function MaidCoffeeGuestOptionCell:SetClickCallBack(callBack)
    self.callBack = callBack
end

function MaidCoffeeGuestOptionCell:RefreshShow(data)
    self.data = data
    if self.data.type == MaidCoffeeConstants.OptionType.Guest then
        CfUtils.FillText(self.TextDesc,data.data.collectVo.name)
    elseif self.data.type == MaidCoffeeConstants.OptionType.Business then
        local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
        local data = maidCoffeeHomeDojo:GetMerchantData()
        if not isNull(data) then
            CfUtils.FillText(self.TextDesc,data.merchant.name)
        end
    end
end

function MaidCoffeeGuestOptionCell:OnOptionNodeClick()
    if not isNull(self.callBack) then
        self.callBack(self.data)
    end
end

function MaidCoffeeGuestOptionCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return MaidCoffeeGuestOptionCell